    "本地插件进程会以当前用户权限运行，并不是操作系统沙箱；capabilities 只限制 MinCode 代为提供的 API。仅安装并启用可信来源。",
  "plugins.declarativePreviewNotice": "这是声明式插件：只包含数据（如快捷键方案），没有可执行文件、界面或权限申请，安装和启用都不会运行任何进程。",
  "plugins.enableLocalConfirm":
    "该插件声明的 capabilities：{capabilities}。本地插件进程不是操作系统沙箱，会以当前用户权限运行。仅在信任来源时启用。",
  "plugins.capabilityDatabaseDriver":
    "数据库驱动（database.driver）：该插件可作为数据库驱动运行。绑定到其驱动的每个连接的主机、用户名、密码等凭据都会交给插件，由插件以当前用户权限直接连接这些数据库。仅在信任来源时绑定连接。",
  "plugins.capabilityDatabaseSchema":
    "数据库结构只读（database.schema）：该插件可以列出已保存连接的名称和类型；你授权某个连接后，它能读取该连接的库、表、字段、索引和注释。不会拿到主机、账号、密码，也不能执行 SQL 或读取表数据。把结果集交给它的服务时，也会附带连接、库、表的名称。",
  "plugins.capabilityRemoteContext":
    "远程对象（remote.context）：你在 SSH 连接、SFTP 文件、Redis 键、HTTP 请求的菜单中选择这个插件的操作时，它会收到该对象的地址或名称（SSH 主机与用户名、远程路径、Redis 键名、去掉查询参数的请求地址）。它拿不到密码、密钥或 Redis 的值。把 SFTP 文件或 HTTP 响应交给它的服务时，也会附带远程路径与连接端点、去掉查询参数的请求地址。",
  "plugins.capabilityUiWasm":
    "WebAssembly（ui.wasm）：这个插件的页面可以运行 WebAssembly 编译代码（例如解码器、解析器）。它仍运行在同一个隔离页面中，不能联网，也拿不到页面以外的数据。",
  "plugins.capabilityAiConfig":
    "AI 设置（ai.config）：可向 AI 设置提交模型配置、连接器和技能，写入前需你确认。插件读不到 MinCode 已保存的设置和 API Key；新增的连接器默认关闭。",
